@section('jqueryScript')
<script>
document.addEventListener('DOMContentLoaded', function () {
    const hidden = document.getElementById('team-members'), input = document.getElementById('member-input'), tags = document.getElementById('member-tags'), box = document.getElementById('member-box'); let members = (hidden.value || '').split(/[\r\n,;]+/).map(value => value.trim()).filter(Boolean);
    const render = () => { tags.innerHTML = ''; members.forEach((member, index) => { const tag = document.createElement('span'); tag.className = 'team-tag'; tag.append(document.createTextNode(member)); const remove = document.createElement('button'); remove.type = 'button'; remove.setAttribute('aria-label', `Xóa ${member}`); remove.textContent = '×'; remove.addEventListener('click', () => { members.splice(index, 1); render(); }); tag.append(remove); tags.append(tag); }); hidden.value = members.join(', '); document.getElementById('summary-members').textContent = `${members.length + 1} người`; };
    const add = () => { input.value.split(/[,;\n]/).map(value => value.trim()).filter(Boolean).forEach(value => { if (!members.some(member => member.toLowerCase() === value.toLowerCase())) members.push(value); }); input.value = ''; render(); };
    input.addEventListener('keydown', event => { if (event.key === 'Enter' || event.key === ',' || event.key === ';') { event.preventDefault(); add(); } if (event.key === 'Backspace' && !input.value && members.length) { members.pop(); render(); } }); input.addEventListener('blur', () => { if (input.value.trim()) add(); }); box.addEventListener('click', () => input.focus()); render();
    const name = document.getElementById('team-name'), description = document.getElementById('team-description'), summaryName = document.getElementById('summary-team-name'), summaryType = document.getElementById('summary-team-type'), customWrap = document.getElementById('custom-team-type-wrap'), customInput = document.getElementById('team_type_custom'); const typeNames = {technical: 'Kỹ thuật & CNTT', marketing: 'Marketing & Kinh doanh', business: 'Vận hành & Doanh nghiệp', other: 'Khác'};
    name.addEventListener('input', () => summaryName.textContent = name.value.trim() || 'Chưa đặt tên'); document.querySelectorAll('[name="team_type"]').forEach(radio => radio.addEventListener('change', () => { const other = radio.checked && radio.value === 'other'; customWrap.classList.toggle('is-hidden', !other); customInput.required = other; summaryType.textContent = other ? (customInput.value.trim() || 'Khác') : typeNames[radio.value]; })); customInput.addEventListener('input', () => { if (document.querySelector('[name="team_type"]:checked')?.value === 'other') summaryType.textContent = customInput.value.trim() || 'Khác'; }); document.querySelectorAll('[data-focus]').forEach(button => button.addEventListener('click', () => document.getElementById(button.dataset.focus).focus())); document.querySelector('[name="team_type"]:checked')?.dispatchEvent(new Event('change'));
});
</script>
@endsection
